  $lent=function($h){ $rows=array(); if(preg_match_all('/<tbody>(.*?)<\/tbody>/su',$h,$tb)&&preg_match_all('/<tr>(.*?)<\/tr>/su',$tb[1][0],$tr)){ foreach($tr[1] as $t){ $rows[]=trim(preg_replace('/\s+/',' ',wp_strip_all_tags(html_entity_decode($t)))); } } return array('n'=>count($rows),'pvz'=>array_slice($rows,0,6),'foot'=>preg_match('/<tfoot>(.*?)<\/tfoot>/su',$h,$tf)?trim(preg_replace('/\s+/',' ',wp_strip_all_tags(html_entity_decode($tf[1])))):'','h1'=>preg_match('/<h1 class="dl-h1">(.*?)<\/h1>/su',$h,$h1)?trim(preg_replace('/\s+/',' ',wp_strip_all_tags($h1[1]))):'','pdf_urls'=>preg_match_all('/href="([^"]*v=dok_pdf[^"]*)"/su',$h,$pu)?count($pu[1]):0,'gen_urls'=>preg_match_all('/href="([^"]*v=dok_gen[^"]*)"/su',$h,$gu)?array_map('html_entity_decode',array_slice($gu[1],0,2)):array(),'first_pdf'=>preg_match('/href="([^"]*v=dok_pdf[^"]*)"/su',$h,$fp)?html_entity_decode($fp[1]):'','juosta_sask'=>(int)preg_match('/>Sąskaitos</u',$h)); };
