      $r=$get($gu); parse_str((string)parse_url($r['h']['loc'],PHP_URL_QUERY),$q); $o['gen']=array('code'=>$r['code'],'pd_ok'=>$q['pd_ok']??null,'pd_nr'=>$q['pd_nr']??null,'loc_view'=>$q['view']??null);
      wp_cache_flush(); $x=wc_get_order($gid); $pdf=(string)$x->get_meta('_petshop_completed_pdf'); $o['gen_po']=array('pdf'=>basename($pdf),'yra'=>$pdf&&file_exists($pdf),'dydis'=>$pdf&&file_exists($pdf)?filesize($pdf):0); }
    // skydelis dok
    $n=wp_create_nonce('ps_dl_zurnalas'); foreach(array(35434,35436,35414) as $id){ $r=wp_remote_get(admin_url('admin-ajax.php?action=ps_dl_skydelis&id='.$id.'&n='.$n),array('cookies'=>$cs,'timeout'=>60,'sslverify'=>false)); $d=json_decode((string)wp_remote_retrieve_body($r),true)['data']??array(); $o['sk_dok'][$id]=$d['dok']??'NĖRA'; }
    $o['temp_liko']=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}snippets WHERE name LIKE 'TEMP%'");
    $J($o);
  }
  if($f==='T2'){
    $o['versija']=Petshop_Darbalaukis::VERSIJA; $n=wp_create_nonce('ps_dl_zurnalas'); foreach(array(35434,35436,35414) as $id){ $r=wp_remote_get(admin_url('admin-ajax.php?action=ps_dl_skydelis&id='.$id.'&n='.$n),array('cookies'=>$cs,'timeout'=>60,'sslverify'=>false)); $d=json_decode((string)wp_remote_retrieve_body($r),true)['data']??array(); $o['sk'][$id]=array('suma'=>$d['suma']??null,'apmok'=>$d['apmok']??null,'dok'=>count($d['dok']??array())); }
