    foreach(array(35434,35414,35436) as $id){ $x=wc_get_order($id); $o['wc_totals'][$id]=array('formatted'=>wp_strip_all_tags($x->get_formatted_order_total()),'rows'=>array_keys($x->get_order_item_totals())); }
