    $_GET['view']='saskaitos'; ob_start(); $rm->invoke(null); $h=ob_get_clean(); $o['html_len']=strlen($h); $o['last_error']=$wpdb->last_error; $o['last_query']=mb_substr($wpdb->last_query,0,3000);
    $o['role_caps']=array_keys(array_filter((array)(get_role('ps_darbuotojas')?get_role('ps_darbuotojas')->capabilities:array())));
