      array('n'=>'s1617_e6_skydelis_35434','u'=>admin_url('admin.php?page=ps-desk&eile=visi&q=35434&atidaryti=35434'),'w'=>1400,'eval'=>"({dok:(document.getElementById('skDokT')||{}).innerText||'',blk:(document.getElementById('skDok')||{}).style?document.getElementById('skDok').style.display:'',foot:(document.getElementById('skV')||{}).innerText||''})")
    );
